	@Test
	void writesOwnedUtf8WithoutMaterializingValues() throws Exception {
		List<EncodedValue> terms = List.of(
				EncodedValue.iri(utf8("http://example.org/名/"), utf8("item\ud83d\ude80")),
				EncodedValue.iri(utf8("u:"), utf8("short")),
				EncodedValue.bnode(utf8("blank-名")),
				EncodedValue.literal(utf8("nul\u0000 \ud83d\ude80"), CoreDatatype.XSD.STRING),
				EncodedValue.literal(utf8("00042"), CoreDatatype.XSD.INTEGER),
				EncodedValue.literal(utf8("not a number"), CoreDatatype.XSD.DOUBLE),
				EncodedValue.literal(utf8("value"), EncodedValue.iri(utf8("http://example.org/types/"), utf8("数"))),
				EncodedValue.languageLiteral(utf8("bonjour"), utf8("fr"), Literal.BaseDirection.NONE),
				EncodedValue.languageLiteral(utf8("مرحبا"), utf8("ar"), Literal.BaseDirection.RTL));
		Object scope = new Object();
		List<BindingSet> rows = new ArrayList<>();
		List<BindingSet> expected = new ArrayList<>();
		for (int i = 0; i < terms.size(); i++) {
			rows.add(new EncodedRow(ONE_COLUMN, scope, new long[] { i }, terms.get(i)));
			expected.add(new ListBindingSet(ONE_COLUMN, terms.get(i).toValue(VF)));
		}

		assertEquals(expected, parse(serialize(ONE_COLUMN, rows, true)));
		assertEquals(expected, parse(serialize(ONE_COLUMN, rows, false)));
	}

	@Test
	void scopedIdsSkipPayloadFetchForConsecutiveRepeats() throws Exception {
		Object scope = new Object();
		EncodedValue first = EncodedValue.literal(utf8("first"), CoreDatatype.XSD.STRING);
		EncodedValue second = EncodedValue.literal(utf8("second"), CoreDatatype.XSD.STRING);
		AtomicInteger fetches = new AtomicInteger();
		List<BindingSet> rows = new ArrayList<>();
		List<BindingSet> expected = new ArrayList<>();
		for (int id : new int[] { 1, 1, 2, 1, 2, 1, 2 }) {
			EncodedValue term = id == 1 ? first : second;
			EncodedRow row = new EncodedRow(ONE_COLUMN, scope, new long[] { id }, term);
			row.fetches = fetches;
			rows.add(row);
			expected.add(new ListBindingSet(ONE_COLUMN, term.toValue(VF)));
		}

		assertEquals(expected, parse(serialize(ONE_COLUMN, rows, true)));
		assertEquals(6, fetches.get(), "Only the consecutive repeat skips fetching its encoded payload");
	}

