	@Test
	void declaresANamespaceOnlyWhenItsRepetitionCanPayForTheDeclaration() throws Exception {
		String namespace = "http://example.org/";
		Object scope = new Object();
		List<BindingSet> rows = new ArrayList<>();
		for (String local : List.of("a", "b", "a", "c")) {
			rows.add(new EncodedRow(ONE_COLUMN, scope, new long[] { local.charAt(0) },
					EncodedValue.iri(utf8(namespace), utf8(local))));
		}
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		DataOutputStream data = new DataOutputStream(expected);
		data.write(new byte[] { 'B', 'R', 'T', 'R' });
		data.writeInt(4);
		data.writeInt(1);
		writeString(data, "value");
		data.writeByte(4); // URI
		writeString(data, namespace + "a");
		data.writeByte(2); // NAMESPACE
		data.writeInt(0);
		writeString(data, namespace);
		for (String local : List.of("b", "a", "c")) {
			data.writeByte(3); // QNAME
			data.writeInt(0);
			writeString(data, local);
		}
		data.writeByte(127);

		assertArrayEquals(expected.toByteArray(), serialize(ONE_COLUMN, rows, true));
	}

