	@Test
	void encodedIdsDoNotRepeatStaleCellsAfterOrdinaryRows() throws Exception {
		List<String> names = List.of("value", "anchor");
		EncodedValue a = EncodedValue.literal(utf8("encoded A"), CoreDatatype.XSD.STRING);
		EncodedValue anchor = EncodedValue.bnode(utf8("anchor"));
		BindingSet encoded = new EncodedRow(names, new Object(), new long[] { 1, 2 }, a, anchor);
		BindingSet expectedEncoded = new ListBindingSet(names, a.toValue(VF), anchor.toValue(VF));
		BindingSet changed = new ListBindingSet(names, VF.createLiteral("ordinary B"), anchor.toValue(VF));
		BindingSet unbound = new ListBindingSet(names, null, anchor.toValue(VF));
		BindingSet empty = new ListBindingSet(names, null, null);
		// Reuse the same scoped IDs after ordinary output changes and clears the first column. The final
		// empty row must preserve the last nonempty row's repeat basis when encoded output resumes.
		List<BindingSet> rows = List.of(encoded, changed, encoded, unbound, encoded, empty, encoded);

		assertEquals(List.of(expectedEncoded, changed, expectedEncoded, unbound, expectedEncoded, empty,
				expectedEncoded), parse(serialize(names, rows, true)));
	}

