	@Test
	void largeEncodedValuesKeepOutputStagingBounded() throws Exception {
		List<String> names = List.of("left", "right");
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		writer.startQueryResult(names);
		Object scope = new Object();
		EncodedValue large = EncodedValue.literal(utf8("中".repeat(2000)), CoreDatatype.XSD.STRING);
		for (int phase = 0; phase < 2; phase++) {
			for (int id = phase * 400; id < (phase + 1) * 400; id++) {
				writer.handleSolution(new EncodedRow(names, scope, new long[] { id, ~id }, large, large));
				writer.handleSolution(new EncodedRow(names, scope, new long[] { ~id, id }, large, large));
			}
		}
		EncodedValue oversized = EncodedValue.literal(utf8("\ud83d\ude80".repeat(20000)), CoreDatatype.XSD.STRING);
		writer.handleSolution(new EncodedRow(names, scope, new long[] { 99999, 99998 }, oversized, oversized));
		writer.handleSolution(new EncodedRow(names, scope, new long[] { 99998, 99999 }, oversized, oversized));
		byte[] rowBuffer = (byte[]) field(field(writer, "out"), "buffer");
		assertNotNull(rowBuffer, "The multi-column workload must exercise row staging");
		assertTrue(rowBuffer.length <= 4096, "Row staging must stay bounded regardless of payload size");
		assertTrue(((byte[]) field(writer, "stringBuffer")).length <= 4100,
				"UTF-8 scratch must stay bounded regardless of payload size");
		writer.endQueryResult();
		List<BindingSet> parsed = parse(output.toByteArray());
		assertEquals(1602, parsed.size());
		BindingSet expectedLarge = new ListBindingSet(names, large.toValue(VF), large.toValue(VF));
		for (int index = 0; index < 1600; index++) {
			assertEquals(expectedLarge, parsed.get(index));
		}
		BindingSet expectedOversized = new ListBindingSet(names, oversized.toValue(VF), oversized.toValue(VF));
		assertEquals(expectedOversized, parsed.get(1600));
		assertEquals(expectedOversized, parsed.getLast());
	}

	@Test
	void doesNotRetryAFailedEncodedRecordWrite() throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		IOException failure = new IOException("record failure");
		class FailingOutput extends OutputStream {
			boolean fail;
			int failedWrites;

			@Override
			public void write(int value) {
				output.write(value);
			}

			@Override
			public void write(byte[] bytes, int offset, int length) throws IOException {
				if (fail) {
					failedWrites++;
					throw failure;
				}
				output.write(bytes, offset, length);
			}
		}
		FailingOutput target = new FailingOutput();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(target);
		Object scope = new Object();
		EncodedValue a = EncodedValue.literal(utf8("A"), CoreDatatype.XSD.STRING);
		EncodedValue b = EncodedValue.literal(utf8("B"), CoreDatatype.XSD.STRING);
		EncodedRow first = new EncodedRow(ONE_COLUMN, scope, new long[] { 1 }, a);
		EncodedRow second = new EncodedRow(ONE_COLUMN, scope, new long[] { 2 }, b);
		writer.startQueryResult(ONE_COLUMN);
		writer.handleSolution(first);
		writer.handleSolution(second);
		target.fail = true;
		TupleQueryResultHandlerException caught = assertThrows(TupleQueryResultHandlerException.class,
				() -> writer.handleSolution(first));
		assertSame(failure, caught.getCause());
		writer.getOutputStream().flush();
		assertEquals(1, target.failedWrites, "Cleanup must not retry a failed sink write");
		target.fail = false;
		writer.handleSolution(first);
		writer.endQueryResult();

		assertEquals(List.of(new ListBindingSet(ONE_COLUMN, a.toValue(VF)),
				new ListBindingSet(ONE_COLUMN, b.toValue(VF)), new ListBindingSet(ONE_COLUMN, a.toValue(VF))),
				parse(output.toByteArray()));
	}

	private static Object field(Object object, String name) throws Exception {
		Field field = object.getClass().getDeclaredField(name);
		field.setAccessible(true);
		return field.get(object);
	}

	private static byte[] serialize(List<String> names, List<BindingSet> rows, boolean plainStrings) {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		writer.getWriterConfig().set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, plainStrings);
		writer.startQueryResult(names);
		rows.forEach(writer::handleSolution);
		writer.endQueryResult();
		return output.toByteArray();
	}

	private static List<BindingSet> parse(byte[] bytes) throws Exception {
		QueryResultCollector collector = new QueryResultCollector();
		BinaryQueryResultParser parser = new BinaryQueryResultParser();
		parser.setQueryResultHandler(collector);
		parser.parseQueryResult(new ByteArrayInputStream(bytes));
		return collector.getBindingSets();
	}

	private static byte[] utf8(String text) {
		return text.getBytes(StandardCharsets.UTF_8);
	}

	private static void writeString(DataOutputStream output, String text) throws IOException {
		byte[] bytes = utf8(text);
		output.writeInt(bytes.length);
		output.write(bytes);
	}

	private static class EncodedRow extends AbstractBindingSet implements EncodedBindingSet {
		private static final long serialVersionUID = 1L;
		private final List<String> names;
		private final Object scope;
		private final long[] ids;
		private final EncodedValue[] values;
		private AtomicInteger fetches = new AtomicInteger();

		private EncodedRow(List<String> names, Object scope, long[] ids, EncodedValue... values) {
			this.names = names;
			this.scope = scope;
			this.ids = ids;
			this.values = values;
		}

		@Override
		public Object getValueScope() {
			return scope;
		}

		@Override
		public boolean hasEncodedValue(int index) {
			return values[index] != null;
		}

		@Override
		public long getValueId(int index) {
			return ids[index];
		}

		@Override
		public EncodedValue getEncodedValue(int index) {
			fetches.incrementAndGet();
			return values[index];
		}

		@Override
		public int getBindingCount() {
			return names.size();
		}

		@Override
		public String getBindingName(int index) {
			return names.get(index);
		}

		@Override
		public Object getBindingLayoutIdentity() {
			return names;
		}

		@Override
		public boolean hasBinding(int index) {
			return values[index] != null;
		}

		@Override
		public Value getValue(int index) {
			throw new AssertionError("Encoded values must not be materialized");
		}

		@Override
		public Value getValue(String name) {
			throw new AssertionError("Physical columns must not be looked up by name");
		}

		@Override
		public boolean isEmpty() {
			return size() == 0;
		}

		@Override
		public int size() {
			int count = 0;
			for (EncodedValue value : values) {
				if (value != null) {
					count++;
				}
			}
			return count;
		}

		@Override
		public Set<String> getBindingNames() {
			throw new AssertionError("No generic binding enumeration is required");
		}

		@Override
		public Binding getBinding(String name) {
			throw new AssertionError("No generic binding access is required");
		}

		@Override
		public boolean hasBinding(String name) {
			throw new AssertionError("No generic binding access is required");
		}

		@Override
		public Iterator<Binding> iterator() {
			throw new AssertionError("No generic binding enumeration is required");
		}
	}
